function lazyLoad(){const n=document.querySelectorAll(".lazy-img"),t=function(n,t){n.forEach(n=>{n.isIntersecting&&(n.target.src=n.target.dataset.src,t.unobserve(n.target))})},i=new IntersectionObserver(t,{root:null,threshold:.2});n.forEach(n=>i.observe(n))}function homePageSliderLazyLoad(){const n=document.querySelectorAll(".lazy-source"),t=function(n,t){n.forEach(n=>{if(n.isIntersecting){const i=n.target.previousElementSibling;n.target.srcset=n.target.dataset.srcset;t.unobserve(n.target);i.classList.add("d-none")}})},i=new IntersectionObserver(t,{root:null,threshold:.2});n.forEach(n=>i.observe(n))}const shrinkText=function(n,t){const i=document.querySelectorAll(n);i.forEach(n=>{n.innerText.length>t?n.innerText=n.innerText.substring(0,t)+"...":""})};let breakpoints={};const productListCarousel=function(n=undefined,t,i){function r(){return window.innerWidth<=760?"horizontal":"horizontal"}breakpoints=i;new Swiper(`#swiperContainer${n}`,{freeMode:{enabled:!0},spaceBetween:t,breakpoints,direction:r(),navigation:{nextEl:".swiper-button-next",prevEl:".swiper-button-prev"}})};